function run() {
  setTimeout(() => {
    try {
      throw new Error('boom');
    } catch (e) {
      console.log('Caught:', e.message); // 'Caught: boom'
    }
  }, 10);
}

run();

async function tryCatch(fn) {
  try {
    const data = await fn();
    return [null, data];
  } catch (error) {
    return [error, undefined];
  }
}

